#!/usr/bin/env python3
"""Regenerate crates/snipdeck-ui/ui/icons.slint from the SVG files in crates/snipdeck-ui/icons/."""
import pathlib

root = pathlib.Path(__file__).resolve().parent.parent / "crates" / "snipdeck-ui"
icons = sorted(p.stem for p in (root / "icons").glob("*.svg"))
lines = [
    "// Phosphor Regular (MIT, see icons/LICENSE-phosphor.txt). The only icon family.",
    "// GENERATED by scripts/ui_icons.py from icons/*.svg. Do not edit.",
    "export global Icons {",
]
lines += [f'    out property <image> {i}: @image-url("../icons/{i}.svg");' for i in icons]
lines.append("}")
(root / "ui" / "icons.slint").write_text("\n".join(lines) + "\n")
